import math
def dist_to_non3(grid):
    n = len(grid)
    dist = [[float('inf')]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 3:
                dist[r][c] = 0
    for _ in range(n):  # Dijkstra-like
        for r in range(n):
            for c in range(n):
                if dist[r][c] < float('inf'):
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < n and 0 <= nc < n:
                            old = dist[nr][nc]
                            new = dist[r][c] + 1
                            if new < old:
                                dist[nr][nc] = new
    return dist

dist_map = dist_to_non3(grid)
print("\nDistance to nearest non-3:")
for row in dist_map:
    print([int(x) if x < float('inf') else 0 for x in row])

